package solution
import "strings"
func CanonicalPath(b string,s []string)(string,bool){if !strings.HasPrefix(b,"/"){return "",false};p:=[]string{};for _,r:=range append([]string{b},s...){for _,x:=range strings.Split(r,"/"){if x==""||x=="."{continue};if x==".."{if len(p)==0{return "",false};p=p[:len(p)-1]}else{p=append(p,x)}}};return "/"+strings.Join(p,"/"),true}
